#include <memory>

class ClassA {};

class ClassB_Safe {
private:
    // Using auto_ptr ensures delete is called upon destruction
    const std::auto_ptr<ClassA> ptr1;
    const std::auto_ptr<ClassA> ptr2;
public:
    // No explicit destructor needed for ptr1/ptr2 cleanup.
    // If new ClassA() for ptr2 throws, ptr1's destructor runs.
    ClassB_Safe() : ptr1(new ClassA()), ptr2(new ClassA()) {}
    // ~ClassB_Safe() {} // Unnecessary
};
